#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> x(m);
    for (int i = 0; i < m; ++i)
        cin >> x[i];

    int t = n, c = 1, b = 0;
    for (int i = 0; i < m; ++i) {
        int y = t - x[i];
        if (x[i] > b)
            ++y;

        int r = y;
        while (y-- > 0)
            cout << c << " ";

        c += r;
        t = x[i];
        b = x[i];
    }

    return 0;
}

